import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Sul concetto di geometria","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/f_geometria-del-piano-euclideo/fb/fbd.md","filePath":"lezioni/f_geometria-del-piano-euclideo/fb/fbd.md"}`),a={name:`lezioni/f_geometria-del-piano-euclideo/fb/fbd.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="sul-concetto-di-geometria" tabindex="-1">Sul concetto di geometria <a class="header-anchor" href="#sul-concetto-di-geometria" aria-label="Permalink to “Sul concetto di geometria”">​</a></h1><h2 id="le-geometrie-e-i-giochi-di-carte" tabindex="-1">Le &quot;geometrie&quot; e i giochi di carte <a class="header-anchor" href="#le-geometrie-e-i-giochi-di-carte" aria-label="Permalink to “Le &quot;geometrie&quot; e i giochi di carte”">​</a></h2><p>Per quanto ti possa sembrare strano, una delle cose più simili alla geometria che esista nel mondo reale è una partita a carte: le regole iniziali sono i postulati che anche qui puoi suddividere in:</p><ul><li>esistenza</li><li>appartenenza</li><li>uguaglianza</li><li>ordine</li></ul><p>E qui puoi vedere come funzionano i postulati:</p><p>se dico esistono <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>40</mn></mrow><annotation encoding="application/x-tex">40</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">40</span></span></span></span> oggetti, <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>10</mn></mrow><annotation encoding="application/x-tex">10</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">10</span></span></span></span> carte di bastoni, ... avrò le carte per una partita di briscola, tresette, scopa, ...</p><p>mentre se dico esistono <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>56</mn></mrow><annotation encoding="application/x-tex">56</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">56</span></span></span></span> oggetti, <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>13</mn></mrow><annotation encoding="application/x-tex">13</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">13</span></span></span></span> carte di quadri, ... avrò le carte per una partita di ramino, scala quaranta, ...</p><p>se gli oggetti sono solo <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>32</mn></mrow><annotation encoding="application/x-tex">32</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">32</span></span></span></span> ... avrò le carte per il poker.</p><p>Variando i postulati dell&#39;uguaglianza e dell&#39;ordine (il tre prende i tre oppure le carte la cui somma è <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>3</mn></mrow><annotation encoding="application/x-tex">3</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">3</span></span></span></span> oppure il tre prende l&#39;asso se il seme è uguale o se il seme corrisponde alla carta scoperta) sceglierò se giocare a scopa o a tresette.</p><p>In pratica i postulati ti obbligano a giocare in un modo piuttosto che in un altro, ma i giochi che fai sono tutti [<strong>ugualmente validi</strong>]{.text-red}, sta a te scegliere poi quello che ti piace di più.</p><p>Similmente, variando i postulati iniziali [<strong>tutte le geometrie che potremo ottenere saranno ugualmente valide</strong>]{.text-red}, saremo poi noi a scegliere quelle che meglio si adattano al mondo reale (in modo da poterlo filtrare tramite il nostro ragionamento per meglio adattarlo alle nostre esigenze).</p><blockquote><p><strong>Esercizio:</strong> Prova a scrivere i postulati per un gioco che conosci.</p></blockquote>`,12)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};